CREATE TABLE configuracion_invitados (actividad_id uuid PRIMARY KEY REFERENCES actividades(id) ON DELETE CASCADE, habilitado boolean NOT NULL DEFAULT false, tolerancia_invitado_segundos integer NOT NULL CHECK(tolerancia_invitado_segundos>40), version bigint NOT NULL DEFAULT 1);
CREATE TABLE invitados_evento (actividad_id uuid NOT NULL REFERENCES actividades(id) ON DELETE CASCADE, persona_id uuid NOT NULL REFERENCES personas(id), nombres varchar(200) NOT NULL CHECK(length(btrim(nombres))>0), activo boolean NOT NULL DEFAULT true, cargado_por uuid NOT NULL REFERENCES cuentas(id), cargado_en timestamptz NOT NULL, version bigint NOT NULL, PRIMARY KEY(actividad_id,persona_id));
CREATE TABLE tokens_qr (id uuid PRIMARY KEY, sesion_id uuid NOT NULL REFERENCES sesiones(id) ON DELETE CASCADE, secreto_hash char(64) NOT NULL UNIQUE, emitido_en timestamptz NOT NULL, expira_en timestamptz NOT NULL, CHECK(expira_en=emitido_en+INTERVAL '40 seconds'));
CREATE INDEX tokens_qr_sesion_idx ON tokens_qr(sesion_id,expira_en);
